  "la-hawla": [
    {
      "ref": "Sahih al-Bukhari 6384",
      "url": "https://sunnah.com/bukhari:6384",
      "text": "Narrated Abu Musa:We were in the company of the Prophet (ﷺ) on a journey, and whenever we ascended a high place, we used to say Takbir (in a loud voice). The Prophet (ﷺ) said, \"O people! Be kind to yourselves, for you are not calling upon a deaf or an absent one, but You are calling an All-Hearer, and an All-Seer.\" Then he came to me as I was reciting silently, \"La haul a wala quwwata illa bil-lah.\" He said, \"O `Abdullah bin Qais! Say: La haul a walaquwata illa bil-lah, for it is one of the treasures of Paradise.\" Or he said, \"Shall I tell you a word which is one of the treasures of Paradise? It is: La haul a wala quwwata illa bil-lah",
      "grades": [
        {
          "by": "Sahih al-Bukhari",
          "grade": "Sahih"
        }
      ]
    }
  ],
  "bismillah-protection": [
    {
      "ref": "Sunan Abi Dawud 5088",
      "url": "https://sunnah.com/abudawud:5088",
      "text": "Narrated Uthman ibn Affan: Aban ibn Uthman said: I heard Uthman ibn Affan (his father) say: I heard the Messenger of Allah (ﷺ) say: If anyone says three times: \"In the name of Allah, when Whose name is mentioned nothing on Earth or in Heaven can cause harm, and He is the Hearer, the Knower\" he will not suffer sudden affliction till the morning, and if anyone says this in the morning, he will not suffer sudden affliction till the evening. Aban was afflicted by some paralysis and when a man who heard the tradition began to look at him, he said to him: Why are you looking at me? I swear by Allah, I did not tell a lie about Uthman, nor did Uthman tell a lie about the Prophet (ﷺ), but that day when I was afflicted by it, I became angry and forgot to say them",
      "grades": [
        {
          "by": "Al-Albani",
          "grade": "Sahih"
        },
        {
          "by": "Zubair Ali Zai",
          "grade": "Sahih"
        }
      ]
    }
  ],
